with with_window as (select e.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from sessions e left join subscriptions sub on e.customer_id = sub.customer_id and e.started_at >= sub.start_date and e.started_at <= date_add(sub.end_date, 7)) select id, customer_id, device, browser, started_at, country, subscription_id, monthly_fee, case when device rlike '^(desktop|mobile)$' then 'GROUP_A' else 'GROUP_B' end as device_zone from with_window order by device, country desc;
